(() => {
  const panel=document.getElementById("damageSimulator"),backdrop=document.getElementById("damageSimulatorBackdrop"),openButton=document.getElementById("damageSimulatorOpen"),closeButton=document.getElementById("damageSimulatorClose");
  if(!panel||!backdrop||!openButton||!closeButton)return;
  const $=id=>document.getElementById(id),number=id=>Number($(id)?.value)||0,format=value=>Math.max(0,Math.round(value)).toLocaleString("zh-CN");
  const presets={normal:{type:"物理",element:"武器属性",ratio:.8,hits:3},s1:{type:"魔法",element:"冰",ratio:.368,hits:6},s2:{type:"魔法",element:"冰",ratio:.357,hits:12},s3:{type:"魔法",element:"冰",ratio:.347,hits:20},ultimate:{type:"魔法",element:"冰",ratio:1.101,hits:54}};
  const readPageStats=()=>{const stats=[...document.querySelectorAll(".stat-box")],read=label=>{const box=stats.find(item=>item.querySelector("span")?.textContent.trim()===label);return Number(box?.querySelector("strong")?.textContent.replaceAll(",",""))||0};$("damageCharacterAtk").value=read("攻击力")||1222;$("damageCharacterInt").value=read("法强")||2512};
  const calculate=()=>{const skill=presets[$("damageSkill").value]||presets.s1,type=$("damageType").value,stat=type==="魔法"?number("damageCharacterInt"):number("damageCharacterAtk"),defense=type==="魔法"?number("damageBossMnd"):number("damageBossDef"),cap=Math.max(1,number("damageCap")),base=stat*stat/Math.max(1,stat+defense)*skill.ratio,rawMin=base,rawAvg=base*1.05,rawMax=base*1.1;$("damageHitMin").textContent=format(Math.min(rawMin,cap));$("damageHitAvg").textContent=format(Math.min(rawAvg,cap));$("damageHitMax").textContent=format(Math.min(rawMax,cap));$("damageCastAvg").textContent=format(Math.min(rawAvg,cap)*skill.hits);$("damageHitCount").textContent=`${skill.hits}段全部命中`;$("damageCapState").textContent=rawMin>=cap?"稳定触顶":rawMax>=cap?"部分触顶":"未触顶";$("damageFormula").textContent=`${type==="魔法"?"法强":"攻击力"} ${format(stat)}² ÷（${format(stat)} + ${type==="魔法"?"魔抗":"防御力"} ${format(defense)}）× 技能倍率`};
  const open=()=>{readPageStats();panel.hidden=false;backdrop.hidden=false;document.body.style.overflow="hidden";calculate()},close=()=>{panel.hidden=true;backdrop.hidden=true;document.body.style.overflow=""};
  openButton.addEventListener("click",open);closeButton.addEventListener("click",close);backdrop.addEventListener("click",close);document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!panel.hidden)close()});panel.addEventListener("input",calculate);panel.addEventListener("change",event=>{if(event.target.id==="damageSkill"){const skill=presets[event.target.value]||presets.s1;$("damageType").value=skill.type;$("damageElement").value=skill.element}calculate()});
})();
